import{_ as o,o as e,c as r,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"MCP 为什么值得用","description":"","frontmatter":{"title":"MCP 为什么值得用"},"headers":[],"relativePath":"md/ai-agent/mcp.md","filePath":"md/ai-agent/mcp.md","lastUpdated":1795424423000}'),s={name:"md/ai-agent/mcp.md"};function l(n,t,i,p,u,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mcp-为什么值得用" tabindex="-1">MCP 为什么值得用 <a class="header-anchor" href="#mcp-为什么值得用" aria-label="Permalink to &quot;MCP 为什么值得用&quot;">​</a></h1><p>MCP（Model Context Protocol）是给&quot;模型调用外部工具&quot;这件事定标准的一套协议。在它之前，每个项目都在自己写一套：A 项目里工具是 JSON、B 项目里是函数签名、C 项目里又变成 prompt 里写死的调用格式。</p><h2 id="它解决的问题不是-调用-是-复用" tabindex="-1">它解决的问题不是&quot;调用&quot;，是&quot;复用&quot; <a class="header-anchor" href="#它解决的问题不是-调用-是-复用" aria-label="Permalink to &quot;它解决的问题不是&quot;调用&quot;，是&quot;复用&quot;&quot;">​</a></h2><p>单个项目里，工具调用怎么写都行。真正麻烦的是这三种场景：</p><ol><li><strong>同一个能力要接多个客户端</strong>（今天接桌面端，明天接聊天机器人，后天接 IDE）。</li><li><strong>多个工具要组合使用</strong>（读文件、查数据库、调 HTTP，分别来自不同实现）。</li><li><strong>换模型或换框架时不想重写工具层</strong>。</li></ol><p>没有标准的时候，一个工具的实现只在它那套框架里有效。有标准之后，工具是独立进程（server），客户端按协议去发现和调用它，换框架不用动工具代码。</p><h2 id="三个核心概念" tabindex="-1">三个核心概念 <a class="header-anchor" href="#三个核心概念" aria-label="Permalink to &quot;三个核心概念&quot;">​</a></h2><ul><li><strong>Server</strong>：提供工具的一方，可以是本地进程（stdio）或远程服务（HTTP/SSE）。</li><li><strong>Client</strong>：宿主程序，负责连接 server、把工具列表交给模型。</li><li><strong>Resources / Tools / Prompts</strong>：三类暴露物。Tool 是模型可以主动调用的动作；Resource 是可读的数据（文件、记录）；Prompt 是预设的提示模板。</li></ul><p>分这三类的意义在于<strong>权限粒度不同</strong>。Resource 是只读的、由应用决定何时读取；Tool 是模型主动发起的、可能有副作用。把它们混在&quot;函数&quot;里，就没法在协议层做权限控制。</p><h2 id="实践里最值得的两点" tabindex="-1">实践里最值得的两点 <a class="header-anchor" href="#实践里最值得的两点" aria-label="Permalink to &quot;实践里最值得的两点&quot;">​</a></h2><p><strong>一，工具发现是动态的。</strong> 客户端不需要预先知道有哪些工具，连上 server 后拉列表。这让&quot;给一个 Agent 临时加能力&quot;变得很轻——加一个 server 配置，能力就多了一组。</p><p><strong>二，stdio 传输让本地能力可复用。</strong> 本地文件系统、本地数据库、本地 CLI 工具，都能被包成一个本地 server，然后被任何支持 MCP 的客户端使用。这是它比纯远程 API 更有意思的地方。</p><h2 id="什么时候不值得上-mcp" tabindex="-1">什么时候不值得上 MCP <a class="header-anchor" href="#什么时候不值得上-mcp" aria-label="Permalink to &quot;什么时候不值得上 MCP&quot;">​</a></h2><ul><li>只有一两个工具，且只在一个应用里用。直接写函数调用更简单。</li><li>需要极低延迟。多一层协议和进程通信，开销不划算。</li><li>团队里没人维护 server 进程的生命周期。</li></ul><p>判断标准很简单：<strong>工具会不会被第二个地方复用</strong>。会，就值得；不会，先别引入复杂度。</p>',15)])])}const h=o(s,[["render",l]]);export{m as __pageData,h as default};
